# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _name_key(student: Student) -> Tuple[str, str]:
    last = student.last_name.lower()
    return (last, student.first_name.lower())

def _require_email(student: Student) -> None:
    if not student.email:
        raise ProjectError(
            f"no email for student: {student.display_name}"
        )

def _widths(cells: Sequence[tuple]) -> List[int]:
    return [max(map(len, column)) for column in zip(*cells)]

def _line(cell: tuple, widths: Sequence[int]) -> str:
    padded = [
        text.ljust(wide) for text, wide in zip(cell, widths)
    ]
    return "  ".join(padded).rstrip()

def _align(students: Sequence[Student]) -> List[str]:
    cells = [
        (item.display_name, item.section, item.email)
        for item in students
    ]
    widths = _widths(cells)
    return [_line(cell, widths) for cell in cells]

# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Name, section and email columns, sorted by name."""
    if not students:
        raise ProjectError("no students for contact sheet")
    ordered = sorted(students, key=_name_key)
    for student in ordered:
        _require_email(student)
    return _align(ordered)
